def seed_gbr_marine_species(apps, schema_editor):
    Ecosystem = apps.get_model("explorer", "Ecosystem")
    MarineSpecies = apps.get_model("explorer", "MarineSpecies")
    ReferenceSource = apps.get_model("explorer", "ReferenceSource")
    SpeciesEcosystem = apps.get_model("explorer", "SpeciesEcosystem")

    # 1. Tạo hoặc lấy các bản ghi ReferenceSource mà không gây trùng lặp
    ref_objects = {}
    for key, ref_data in SEED_REFERENCES.items():
        ref_obj, _ = ReferenceSource.objects.get_or_create(
            title=ref_data["title"],
            publisher=ref_data["publisher"],
            defaults={
                "published_year": ref_data["published_year"],
                "url": ref_data["url"],
                "notes": ref_data["notes"],
            },
        )
        ref_objects[key] = ref_obj

    # 2. Tạo hoặc lấy 5 bản ghi MarineSpecies và 6 bản ghi SpeciesEcosystem
    for item in SEED_SPECIES:
        reference_keys = item["reference_keys"]
        ecosystem_links = item["ecosystem_links"]
        species_fields = {
            k: v
            for k, v in item.items()
            if k not in ("reference_keys", "ecosystem_links")
        }

        species_obj, _ = MarineSpecies.objects.get_or_create(
            slug=species_fields["slug"],
            defaults=species_fields,
        )

        for ref_key in reference_keys:
            if ref_key in ref_objects:
                species_obj.references.add(ref_objects[ref_key])

        for link_data in ecosystem_links:
            ecosystem_obj = Ecosystem.objects.filter(slug=link_data["ecosystem_slug"]).first()
            if ecosystem_obj:
                SpeciesEcosystem.objects.get_or_create(
                    species=species_obj,
                    ecosystem=ecosystem_obj,
                    defaults={
                        "local_depth_range_text": link_data["local_depth_range_text"],
                        "adaptation_notes": link_data["adaptation_notes"],
                        "is_key_species": link_data["is_key_species"],
                    },
                )


def remove_seeded_gbr_marine_species(apps, schema_editor):
    MarineSpecies = apps.get_model("explorer", "MarineSpecies")
    ReferenceSource = apps.get_model("explorer", "ReferenceSource")
    SpeciesEcosystem = apps.get_model("explorer", "SpeciesEcosystem")

    seeded_species_slugs = [item["slug"] for item in SEED_SPECIES]
    seeded_ecosystem_slugs = ["gbr-coral-reef", "gbr-seagrass-meadow"]

    # Chỉ xóa các liên kết thuộc bộ seed GBR
    SpeciesEcosystem.objects.filter(
        species__slug__in=seeded_species_slugs,
        ecosystem__slug__in=seeded_ecosystem_slugs,
    ).delete()

    # Chỉ xóa loài nếu không còn liên kết với bất kỳ hệ sinh thái nào khác do người dùng thêm
    MarineSpecies.objects.filter(
        slug__in=seeded_species_slugs,
        ecosystem_links__isnull=True,
    ).delete()

    # Chỉ xóa các ReferenceSource của đợt seed này nếu không còn gắn với bất kỳ loài hoặc ExplorerItem nào
    seeded_ref_titles = [ref["title"] for ref in SEED_REFERENCES.values()]
    ReferenceSource.objects.filter(
        title__in=seeded_ref_titles,
        items__isnull=True,
        marine_species__isnull=True,
    ).delete()


class Migration(migrations.Migration):

    dependencies = [
        ("explorer", "0006_marinespecies_speciesecosystem_and_more"),
    ]

    operations = [
        migrations.RunPython(
            seed_gbr_marine_species,
            reverse_code=remove_seeded_gbr_marine_species,
        ),
    ]

